/** Explicit physical projections and subject attribution. [COMP:crm/privacy-export]
 * Update the matching spec and real-database coverage test when changing a domain.
 */
export type CrmPrivacyScope = 'workspace' | 'contact'
export type CrmPrivacyClassification = 'included' | 'redacted' | 'excluded'
export type CrmPrivacyCoverageEntry = {
  domain:string
  columns:readonly string[]
  excludedColumns:readonly string[]
  workspaceWhere:string
  workspacePredicate?:string
  subjectWhere:string|null
  subjectRedactions:Record<string,string>
  transforms:Record<string,string>
  orderBy:string
  reason:string
}

const campaignPrivacyEntry = (
  domain: string,
  columns: readonly string[],
  subjectWhere: string | null,
  excludedColumns: readonly string[] = [],
  subjectRedactions: Record<string, string> = {},
  orderBy = 't.id',
): CrmPrivacyCoverageEntry => ({
  domain, columns, excludedColumns, workspaceWhere: 'true', subjectWhere,
  subjectRedactions, transforms: {}, orderBy,
  reason: subjectWhere
    ? 'Native campaign evidence is exported with explicit subject attribution and private replay material removed.'
    : 'Workspace campaign configuration or aggregate evidence has no safe single-subject projection.',
})

