/** Parameters: workspace UUID and optional subject UUID. Suppression tuples stay in a temporary table. */
export function crmPrivacyDomainSql(entry:CrmPrivacyCoverageEntry,scope:CrmPrivacyScope):string {
  const fields=entry.columns.filter(c=>!entry.excludedColumns.includes(c)).flatMap(c=>[
    "'"+c+"'",scope==='contact' && Object.hasOwn(entry.subjectRedactions,c)?entry.subjectRedactions[c]!:entry.transforms[c] ?? 't.'+c,
  ])
  const where=scope==='contact'?entry.subjectWhere ?? 'false':entry.workspaceWhere
  return 'WITH privacy_args AS (SELECT $1::uuid workspace_id,$2::uuid subject_id),'
    +' projected AS (SELECT jsonb_build_object('+fields.join(',')+')::text AS payload FROM '+entry.domain+' t'
    +' WHERE '+(entry.workspacePredicate ?? 't.workspace_id=$1')+' AND ('+where+') ORDER BY '+entry.orderBy+')'
    +' SELECT CASE WHEN octet_length(payload)<=67108864 THEN payload ELSE NULL END AS payload,octet_length(payload) AS bytes FROM projected'
}
export function crmPrivacyClassification(entry:CrmPrivacyCoverageEntry,scope:CrmPrivacyScope):CrmPrivacyClassification {
  if(scope==='workspace' && entry.workspaceWhere==='false' || scope==='contact' && entry.subjectWhere===null)return 'excluded'
  return entry.excludedColumns.length || (scope==='contact' && Object.keys(entry.subjectRedactions).length)?'redacted':'included'
}
